import { getAuthenticatedUser } from "@/lib/firebase-admin";
import { getDatabase } from "@/lib/db";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type RouteContext = { params: Promise<{ id: string }> };

function unauthorized() {
  return Response.json({ error: "Authentication required" }, { status: 401 });
}

export async function PATCH(request: Request, context: RouteContext) {
  const user = await getAuthenticatedUser(request);
  if (!user) return unauthorized();

  const { id } = await context.params;
  const body = (await request.json().catch(() => ({}))) as {
    title?: unknown;
    content?: unknown;
  };
  const title = typeof body.title === "string" ? body.title : "";
  const content = typeof body.content === "string" ? body.content : "";
  const database = await getDatabase();
  const result = await database.execute({
    sql: "UPDATE notes SET title = ?, content = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ? AND user_id = ?",
    args: [title, content, id, user.uid],
  });

  if (result.rowsAffected === 0) {
    return Response.json({ error: "Note not found" }, { status: 404 });
  }

  const note = await database.execute({
    sql: "SELECT id, title, content, created_at, updated_at FROM notes WHERE id = ? AND user_id = ?",
    args: [id, user.uid],
  });

  return Response.json(note.rows[0]);
}

export async function DELETE(request: Request, context: RouteContext) {
  const user = await getAuthenticatedUser(request);
  if (!user) return unauthorized();

  const { id } = await context.params;
  const database = await getDatabase();
  const result = await database.execute({
    sql: "DELETE FROM notes WHERE id = ? AND user_id = ?",
    args: [id, user.uid],
  });

  if (result.rowsAffected === 0) {
    return Response.json({ error: "Note not found" }, { status: 404 });
  }

  return new Response(null, { status: 204 });
}
